function readPullRequest(body) {
  if (body?.eventType !== "git.pullrequest.created") return null;
  const { message, resource } = body;
  if (
    typeof message?.markdown !== "string" ||
    !message.markdown.trim() ||
    typeof resource?.createdBy?.uniqueName !== "string" ||
    typeof resource.createdBy.displayName !== "string" ||
    !Array.isArray(resource.reviewers)
  ) {
    throw new Error("The pull request event needs the full Azure DevOps resource and message");
  }
  return {
    markdown: message.markdown,
    creator: resource.createdBy,
    reviewers: resource.reviewers,
  };
}
const pullRequest = readPullRequest($input.first().json.body);
return pullRequest ? [{ json: pullRequest }] : [];

function makeMessage(pr, rows) {
  const normalize = (value) => (typeof value === "string" ? value.trim().toLowerCase() : "");
  const mapping = new Map();
  for (const { TfsAccount, UserName, DingTalkMobile } of rows) {
    const account = normalize(TfsAccount);
    if (!account && !UserName && !DingTalkMobile) continue;
    const mobile = typeof DingTalkMobile === "string" ? DingTalkMobile.trim() : "";
    if (!account || mapping.has(account) || (DingTalkMobile && !/^\+?\d{6,15}$/.test(mobile))) {
      throw new Error(
        "Use distinct TfsAccount values and mobile numbers stored as text in the reviewer mapping",
      );
    }
    mapping.set(account, {
      name: typeof UserName === "string" ? UserName.trim() : "",
      mobile,
    });
  }

  function find(identity) {
    const account = normalize(identity?.uniqueName);
    const shortName = account.split("\\").at(-1).split("@")[0];
    return mapping.get(account) ?? mapping.get(shortName);
  }

  const creatorName = find(pr.creator)?.name;
  let text = pr.markdown;
  if (creatorName && pr.creator.displayName)
    text = text.replace(pr.creator.displayName, () => creatorName);

  const isTeam = (reviewer) =>
    reviewer?.isContainer === true ||
    (reviewer?.isContainer == null &&
      typeof reviewer?.uniqueName === "string" &&
      reviewer.uniqueName.includes("团队"));
  const isAtAll = pr.reviewers.some(isTeam);
  const people = pr.reviewers
    .filter((reviewer) => !isTeam(reviewer))
    .map(find)
    .filter(Boolean);
  const mobiles = [...new Set(people.map(({ mobile }) => mobile).filter(Boolean))];
  const names = isAtAll ? [...new Set(people.map(({ name }) => name).filter(Boolean))] : [];
  const mentions = isAtAll ? ["所有人", ...names] : mobiles;
  if (mentions.length) text += "\n\n请 @" + mentions.join(" @") + " 评审";

  return {
    title: "New PR Notify",
    text,
    atMobiles: !isAtAll && mobiles.length ? mobiles : null,
    isAtAll,
  };
}
const pr = $("Read the new pull request").first().json;
const rows = $input.all().map(({ json }) => json);
const { title, text, atMobiles, isAtAll } = makeMessage(pr, rows);
const timestamp = String(Date.now());
return [
  {
    json: {
      timestamp,
      body: {
        msgtype: "markdown",
        markdown: { title, text },
        at: { ...(atMobiles ? { atMobiles } : {}), isAtAll },
      },
    },
  },
];

const response = $input.first().json;
if (response.errcode !== 0)
  throw new Error(
    "DingTalk rejected the message (" +
      (Number.isInteger(response.errcode) ? response.errcode : "invalid response") +
      ")",
  );
return [{ json: { delivered: true } }];
